        __HAL_DMA_SET_CIRCLUAR_MODE(hacodec->hdma[did], DMA_CIRCULAR);

        /* Set the AUDCODEC Tx DMA transfert complete callback */
        hacodec->hdma[did]->XferCpltCallback = AUDCODEC_DMATxCplt;


