/* Opcodes this server emits. Incoming frames are decoded separately. */
#define WS_OPCODE_TEXT   0x1
#define WS_OPCODE_BINARY 0x2

/**
 * Send one unfragmented frame (server → client, no masking).
 * Caller must hold s_clients_mtx.
 */
static int ws_send_frame_op(int fd, const void* payload, size_t len,
    int opcode)
{
    unsigned char hdr[10];
    int hdr_len = 0;

    hdr[0] = (unsigned char)(0x80 | opcode); /* FIN + opcode */
    if (len < 126) {
        hdr[1] = (unsigned char)len;
        hdr_len = 2;
    } else if (len < 65536) {
        hdr[1] = 126;
        hdr[2] = (unsigned char)(len >> 8);
        hdr[3] = (unsigned char)(len & 0xFF);
        hdr_len = 4;
    } else {
        syslog(LOG_ERR, "[%s] Payload too large: %d\n", TAG, (int)len);
        return -1;
    }

    if (send(fd, hdr, hdr_len, 0) != hdr_len)
        return -1;
    if (send(fd, payload, len, 0) != (int)len)
        return -1;
    return 0;
}

/**
 * Send a text frame. Caller must hold s_clients_mtx.
 */
static int ws_send_frame(int fd, const char* payload, size_t len)
{
    return ws_send_frame_op(fd, payload, len, WS_OPCODE_TEXT);
}

